@-moz-document domain("chat.openai.com") {
  body,
  html,
  .flex,
  .h-full,
  .overflow-hidden,
  .dark,
  main,
  .text-base {
    background-color: #e6ffe6 !important; /* nền xanh lá nhạt */
    color: #003300 !important;            /* chữ xanh đậm */
  }

  button, input, textarea, select {
    background-color: #ccffcc !important;
    color: #004d00 !important;
    border-radius: 8px !important;
    border: 1px solid #00cc44 !important;
  }

  .text-token-text-primary,
  .text-token-text-secondary,
  .prose,
  .markdown {
    color: #003300 !important;
  }

  .bg-black, .bg-gray-900, .dark .bg-gray-800 {
    background-color: #b3ffb3 !important;
  }

  ::selection {
    background: #66ff99 !important;
    color: #003300 !important;
  }

  .group:hover {
    background-color: #ccffcc !important;
  }
}

style.css:
@-moz-document domain("chat.openai.com") {
/* Toàn bộ nền chính */
  html, body, .dark, .h-full, .overflow-hidden, .relative, .w-full {
    background-color: #e6ffe6 !important;
    color: #003300 !important;
  }

  /* Vùng nhập chat */
  textarea, input {
    background-color: #ccffcc !important;
    color: #003300 !important;
    border: 1px solid #00cc66 !important;
    border-radius: 8px !important;
  }

  /* Các tin nhắn AI & người dùng */
  .prose, .markdown, .text-base, .text-token-text-primary, .text-token-text-secondary {
    color: #004d00 !important;
    background-color: #f0fff0 !important;
    border-radius: 10px !important;
    padding: 4px !important;
  }

  /* Các nút bấm */
  button, .btn, .text-sm, .text-white {
    background-color: #66ff99 !important;
    color: #004400 !important;
    border-radius: 12px !important;
    border: 1px solid #00cc66 !important;
  }

  /* Nút gửi */
  .absolute.p-1.md\\:bottom-3.md\\:p-2 {
    background-color: #b3ffcc !important;
  }

  /* Hover + lựa chọn */
  .group:hover {
    background-color: #ccffcc !important;
  }

  ::selection {
    background-color: #99ffcc !important;
    color: #002200 !important;
  }

  /* Thanh bên (sidebar) */
  .bg-black, .dark .bg-gray-800, .text-white {
    background-color: #b3ffb3 !important;
    color: #003300 !important;
  }
}
